import importlib
import builtins
from typing import Any
import pytest

def make_linter(interactive: bool) -> Any:
    class Config:
        def __init__(self, interactive: bool):
            self.interactive = interactive

    class Linter:
        def __init__(self, interactive: bool):
            self.config = Config(interactive)

    return Linter(interactive)

def test_handle_generate_command_interactive_calls_generator_and_returns_zero(monkeypatch):
    linter = make_linter(True)
    gc_module = importlib.import_module('pylint.config._pylint_config.generate_command')

    generator_name = None
    for candidate in ('_generate_config', 'generate_config', '_generate_config_command', 'generate_rcfile', '_generate_rcfile', '_generate_rc'):
        if hasattr(gc_module, candidate):
            generator_name = candidate
            break

    called = {'count': 0}
    def fake_generator(_linter):
        called['count'] += 1

    if generator_name:
        monkeypatch.setattr(gc_module, generator_name, fake_generator, raising=True)

    printed = []
    monkeypatch.setattr(builtins, 'print', lambda *args, **kwargs: printed.append(' '.join(map(str, args))))

    result = __import__('pylint.config._pylint_config.generate_command', fromlist=['handle_generate_command']).handle_generate_command(linter)

    assert result == 0
    if generator_name:
        assert called['count'] == 1
    # Do not rely on exact print behavior; ensure no crash and some output may have occurred
    # Ensure linter state unchanged
    assert linter.config.interactive is True

def test_handle_generate_command_not_interactive_prints_help_and_returns_32(monkeypatch):
    linter = make_linter(False)
    gc_module = importlib.import_module('pylint.config._pylint_config.generate_command')

    generator_name = None
    for candidate in ('_generate_config', 'generate_config', '_generate_config_command', 'generate_rcfile', '_generate_rcfile', '_generate_rc'):
        if hasattr(gc_module, candidate):
            generator_name = candidate
            break

    if generator_name:
        def raise_if_called(_):
            raise AssertionError("Generator should not be called in non-interactive mode")
        monkeypatch.setattr(gc_module, generator_name, raise_if_called, raising=True)

    printed = []
    monkeypatch.setattr(builtins, 'print', lambda *args, **kwargs: printed.append(' '.join(map(str, args))))

    result = __import__('pylint.config._pylint_config.generate_command', fromlist=['handle_generate_command']).handle_generate_command(linter)

    assert result == 32
    assert len(printed) > 0  # Help information should have been printed
    # Ensure linter state unchanged
    assert linter.config.interactive is False

