import pytest
import pylint.lint.expand_modules as expand_modules_module

class TestExpandModules:

    def test_expand_modules_empty_input_returns_empty(self, monkeypatch):
        mods, errs = expand_modules_module.expand_modules([], [], [], [], [])
        assert mods == {}
        assert errs == []

    def test_expand_modules_ignored_files_produce_no_results(self, monkeypatch):
        monkeypatch.setattr(expand_modules_module, "_is_ignored_file", lambda *args, **kwargs: True, raising=False)
        mods, errs = expand_modules_module.expand_modules(['f.py'], [], [], [], [])
        assert mods == {}
        assert errs == []

    def test_expand_modules_import_error_propagates(self, monkeypatch):
        def fake_discover(*args, **kwargs):
            raise ImportError("Cannot import")
        monkeypatch.setattr(expand_modules_module, "discover_package_path", fake_discover, raising=False)
        monkeypatch.setattr(expand_modules_module, "_is_ignored_file", lambda *args, **kwargs: False, raising=False)
        with pytest.raises(ImportError):
            expand_modules_module.expand_modules(['bad'], [], [], [], [])

    def test_expand_modules_discovers_module_path(self, monkeypatch):
        def fake_discover(*args, **kwargs):
            return '/path/base/module.py'
        monkeypatch.setattr(expand_modules_module, "discover_package_path", fake_discover, raising=False)
        monkeypatch.setattr(expand_modules_module, "_is_ignored_file", lambda *args, **kwargs: False, raising=False)
        mods, errs = expand_modules_module.expand_modules(['mod'], ['src'], [], [], [])
        assert isinstance(mods, dict)
        assert '/path/base/module.py' in mods

