def _invoke_same_root_dir(node, import_mod_name):
    importlib.invalidate_caches()
    mod = importlib.import_module("pylint.extensions.private_import")

    # Case 1: top-level function is available
    if hasattr(mod, "same_root_dir"):
        func = getattr(mod, "same_root_dir")
        sig = inspect.signature(func)
        # If function is defined as a staticmethod (node, import_mod_name)
        if len(sig.parameters) == 2:
            return func(node, import_mod_name)
        else:
            # Likely an instance method; attempt to create a dummy instance
            cls = getattr(mod, "PrivateImportChecker", None)
            if cls is None:
                pytest.skip("PrivateImportChecker not found in module")
            dummy = object.__new__(cls)
            return func(dummy, node, import_mod_name)

    # Case 2: function is defined inside the class
    cls = getattr(mod, "PrivateImportChecker", None)
    if cls is not None:
        func = getattr(cls, "same_root_dir", None)
        if func is None:
            pytest.skip("same_root_dir not found on PrivateImportChecker")
        sig = inspect.signature(func)
        if len(sig.parameters) == 3:
            dummy = object.__new__(cls)
            return func(dummy, node, import_mod_name)
        else:
