        self.encoding = encoding
        self.contents = ''
    def write(self, s: str):
        self.contents += s

class RecordingWriter(BaseWriter):
    def __init__(self):
        # Avoid relying on BaseWriter.__init__ signature
        self.stream = None

    def write(self, text: str):
        # Forward writes to the provided stream
        self.stream.write(text)

class DummyLayout(BaseLayout):
    def __init__(self, texts):
        self.texts = texts
        self.accept_calls = 0

    def accept(self, writer):
        self.accept_calls += 1
        for t in self.texts:
            writer.write(t)

