    paths = set()

    def _scan(val):
        if isinstance(val, Path):
            paths.add(str(val.resolve()))
        elif isinstance(val, str):
            p = Path(val)
            if p.suffix == ".py":
                try:
                    paths.add(str(p.resolve()))
                except Exception:
                    pass
        elif isinstance(val, (list, tuple, set)):
            for v in val:
                _scan(v)
        else:
            # dive into attributes if possible
            try:
                for attr in dir(val):
                    if attr.startswith("_"):
