                    try:
                        v = getattr(val, attr)
                    except Exception:
                        continue
                    _scan(v)
            except Exception:
                pass

    for it in items:
        _scan(it)

    if not paths:
        # Fallback: try to extract any path-like substring
        import re
        for it in items:
            s = str(it)
            m = re.search(r'(/[^:\s]+\.py)', s)
            if m:
                paths.add(m.group(1))

    return sorted(paths)


