import io
import pytest

from pylint.reporters.base_reporter import BaseReporter


class DummyText:
    def __init__(self, data: str):
        self.data = data


class DummyChild:
    def __init__(self, children):
        self.children = children


class DummyLayout:
    def __init__(self, report_id, first_child):
        self.report_id = report_id
        self.children = [first_child]


class InvalidText:
    pass


def test_display_reports_updates_text_and_calls_display():
    class Reporter(BaseReporter):
        def __init__(self):
            super().__init__(output=None)
            self._display_calls = 0

        def _display(self, layout):
            self._display_calls += 1

    layout = DummyLayout("RID123", DummyChild([DummyText("initial")]))
    rep = Reporter()

    rep.display_reports(layout)

    assert rep._display_calls == 1
    assert "RID123" in layout.children[0].children[0].data
    assert rep.section == 0


def test_display_reports_no_report_id_no_change():
    class Reporter(BaseReporter):
        def __init__(self):
            super().__init__(output=None)
            self._display_calls = 0

        def _display(self, layout):
            self._display_calls += 1

    layout = DummyLayout(None, DummyChild([DummyText("start")]))
    rep = Reporter()

    rep.display_reports(layout)

    assert layout.children[0].children[0].data == "start"
    assert rep._display_calls == 1
    assert rep.section == 0


def test_display_reports_raises_value_error_on_invalid_structure():
    layout = DummyLayout("RID", DummyChild([InvalidText()]))

    class Reporter(BaseReporter):
        def __init__(self):
            super().__init__(output=None)
            self._display_called = False

        def _display(self, layout):
            self._display_called = True

    rep = Reporter()

    with pytest.raises(ValueError):
        rep.display_reports(layout)

    assert rep._display_called is False

