from pylint.graph import get_cycles

class TestGetCycles:
    def test_two_node_cycle(self):
        graph = {"A": {"B"}, "B": {"A"}}
        cycles = get_cycles(graph)
        cycle_sets = {frozenset(cycle) for cycle in cycles}
        assert frozenset({"A", "B"}) in cycle_sets

    def test_three_node_cycle(self):
        graph = {"A": {"B"}, "B": {"C"}, "C": {"A"}}
        cycles = get_cycles(graph)
        cycle_sets = {frozenset(cycle) for cycle in cycles}
        assert frozenset({"A", "B", "C"}) in cycle_sets

    def test_multiple_cycles(self):
        graph = {"A": {"B"}, "B": {"A"}, "C": {"D"}, "D": {"C"}}
        cycles = get_cycles(graph)
        cycle_sets = {frozenset(cycle) for cycle in cycles}
        assert {frozenset({"A", "B"}), frozenset({"C", "D"})}.issubset(cycle_sets)

    def test_no_cycles(self):
        graph = {"A": {"B"}, "B": {"C"}, "C": {"D"}, "D": set()}
        cycles = get_cycles(graph)
