class TestCreateTestLinterAlt:
    def test_handles_alternate_methods_for_persistence_and_init(self, monkeypatch):
        class FakeGenericTestReporter:
            pass

        class FakePyLinterAlt:
            def __init__(self):
                self.reporter = None
                self.persistent_config = None
                self.checkers_initialized = False
                self.config = {}
                self.calls = []

            def set_reporter(self, reporter):
                self.calls.append(('set_reporter', (reporter,), {}))
                self.reporter = reporter

            def disable_persistent_config(self):
                self.calls.append(('disable_persistent_config', (), {}))
                self.persistent_config = 0

            def initialize_with_checkers(self):
                self.calls.append(('initialize_with_checkers', (), {}))
                self.checkers_initialized = True

        monkeypatch.setattr(gtl, 'PyLinter', FakePyLinterAlt, raising=False)
